LUT_V1_EXP2_PADDING_OFFSET, LUT_V1_EXP2_PADDING_BYTES, LUT_V1_EXP2_PADDING_FILL = 32, 224, 0x3C00
LUT_V1_EXP2_GUARD_BYTES, LUT_V1_EXP2_TABLE_BYTES = 3840, 2052
